-- AYK-190: MySQL 8 source; PostgreSQL is generated by the project translator.
-- Data-only cleanup. Never merge/delete districts or alter IDs.
-- The durable before/after journal is deliberately retained for rollback.
-- Rollback (after a DB backup):
-- UPDATE districts d JOIN district_name_cleanup_070 b ON d.id = b.district_id
-- SET d.name_en = b.old_name_en WHERE BINARY d.name_en = BINARY b.new_name_en;
-- Only restore values still equal to this migration's output; later edits win.
-- Do not delete schema_migrations or the journal when rolling back.

CREATE TABLE IF NOT EXISTS district_name_cleanup_070 (
  district_id BIGINT PRIMARY KEY,
  old_name_en VARCHAR(120) NOT NULL,
  new_name_en VARCHAR(120) NOT NULL,
  recorded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT IGNORE INTO district_name_cleanup_070 (district_id, old_name_en, new_name_en)
SELECT id, name_en, TRIM(REGEXP_REPLACE(name_en, '[[:space:]]+[Dd][Ii][Ss][Tt][.]?[[:space:]]*$', ''))
FROM districts
WHERE name_en REGEXP '[[:space:]]+[Dd][Ii][Ss][Tt][.]?[[:space:]]*$'
  AND TRIM(REGEXP_REPLACE(name_en, '[[:space:]]+[Dd][Ii][Ss][Tt][.]?[[:space:]]*$', '')) <> '';

UPDATE districts d
JOIN district_name_cleanup_070 b ON d.id = b.district_id
SET d.name_en = b.new_name_en
WHERE BINARY d.name_en = BINARY b.old_name_en;
